using System.Linq;using UnityEditor;using UnityEngine;
namespace XuanwuTools { public static class AssetImportProcessor {
 [MenuItem(Common.Menu+"06 Prepare selected copied textures")] public static void Prepare()=>Common.Run(()=>{if(EditorApplication.isPlayingOrWillChangePlaymode)throw new System.Exception("Not in Play Mode");var paths=Selection.objects.Select(AssetDatabase.GetAssetPath).Distinct().Where(p=>p.StartsWith("Assets/XuanwuGenerated/")).Where(p=>AssetImporter.GetAtPath(p) is TextureImporter).ToArray();if(paths.Length==0)throw new System.Exception("Select copied textures under Assets/XuanwuGenerated; no original imports changed");if(!Common.Confirm("Import dry-run",$"{paths.Length} copied textures: max size <=2048, mipmaps on. Do not infer Normal/sRGB or platform override."))return;foreach(var p in paths){var i=(TextureImporter)AssetImporter.GetAtPath(p);i.maxTextureSize=Mathf.Min(i.maxTextureSize,2048);i.mipmapEnabled=true;i.SaveAndReimport();}Common.Report("imports",string.Join("\n",paths));});}}
